client = OpenAI()

def parse_diff(diff: str):
    # 按文件拆分 diff，提取新增行（以 + 开头且非 +++）
    files = {}
    cur = None
    for line in diff.splitlines():
        if line.startswith("+++ "):
            cur = line[4:].strip()
            files[cur] = []
        elif line.startswith("+") and not line.startswith("+++"):
            files[cur].append(line[1:])
    return files

