import hashlib

CACHE = {}

def norm(q: str) -> str:
    return "".join(q.lower().split())        # 去空格转小写，做简易归一

def ask(question: str, llm_fn):
    key = hashlib.md5(norm(question).encode()).hexdigest()
    if key in CACHE:
        return CACHE[key], "cache"           # 命中，不调模型
    ans = llm_fn(question)
    CACHE[key] = ans
    return ans, "llm"

