# 指数退避重试（离线示意，不真 sleep）
def retry(fn, max_t=3):
    for i in range(max_t):
        if fn():
            return f"第{i+1}次成功"
    return "全部失败"

attempts = {"n": 0}
def flaky():
    attempts["n"] += 1
    return attempts["n"] >= 2

