def upsert_session(conn, sid, data):
    with conn.cursor() as cur:                # with 自动归还游标
        cur.execute(
            "INSERT INTO sessions(id,data) VALUES(%s,%s) "
            "ON CONFLICT(id) DO UPDATE SET data=%s",
            (sid, data, data),
        )
    conn.commit()

